package com.northstar.crm.ui;import com.northstar.crm.domain.AuditEvent;import com.northstar.crm.service.AuditService;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.VerticalLayout;import com.vaadin.flow.router.*;import jakarta.annotation.security.RolesAllowed;@Route(value="admin/audit",layout=MainLayout.class)@PageTitle("Audit ledger · Northstar")@RolesAllowed("PLATFORM_ADMIN")public class AuditView extends VerticalLayout {public AuditView(AuditService audit){var grid=new Grid<AuditEvent>();grid.addColumn(a->a.getOccurredAt().toString()).setHeader("Time").setSortable(true);grid.addColumn(AuditEvent::getAction).setHeader("Action");grid.addColumn(AuditEvent::getResourceType).setHeader("Resource");grid.addColumn(a->a.getResourceId()==null?"—":a.getResourceId().toString()).setHeader("Record");grid.addColumn(AuditEvent::getAuthorizationBasis).setHeader("Authorization basis").setFlexGrow(2);grid.setItems(audit.recent());var panel=new VerticalLayout(new Paragraph("Append-only events include actor, before/after context and the decision basis. No edit or delete action exists."),grid);panel.addClassName("panel");add(UiKit.page("IMMUTABLE CONTROL RECORD","Audit ledger","Privileged actions and workflow transitions, newest first.",panel));setPadding(false);setSizeFull();}}
